def readj(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))


def readjl(path: Path):
    return [json.loads(x) for x in path.read_text(encoding="utf-8").splitlines() if x.strip()]


def writejl(path: Path, rows):
    path.write_text("".join(json.dumps(x, ensure_ascii=False, sort_keys=True) + "\n" for x in rows), encoding="utf-8")


def ref(path: Path, **selector):
    return str(path) + "#" + "&".join(f"{k}={v}" for k, v in selector.items())


